const item = $input.first().json;
const g    = $getWorkflowStaticData('global');

// ── Complexity scoring (programmatic, zero LLM cost) ─────────────────────────
const prompt = (item.input_text || '').toLowerCase().trim();
const words  = prompt.split(/\s+/).filter(Boolean);

const analyticalVerbs = [
  'analyse','analyze','evaluate','assess','examine','critically','compare',
  'contrast','discuss','investigate','justify','distinguish','critique'
];
const multiRequirements = [
  'and evaluate','and assess','and examine','and discuss','referencing specific',
  'with examples','policy instruments','case studies','in depth','in detail',
  'and explain why','causes and','advantages and','pros and cons'
];

const hasAnalytical   = analyticalVerbs.some(v => prompt.includes(v));
const hasMultiReq     = multiRequirements.some(p => prompt.includes(p));
const wordCount       = words.length;

let minIterations = 1;
if      (wordCount > 15 && hasAnalytical && hasMultiReq) minIterations = 3;
else if (wordCount > 10 || hasAnalytical)                minIterations = 2;
// else: short/simple/greeting → minIterations = 1

g.reflection_state = {
  iteration:            1,
  input_text:           item.input_text,
  start_time_ms:        item.start_time_ms,
  input_token_estimate: item.input_token_estimate,
  current_draft:        '',
  critic_feedback:      '',
  is_approved:          false,
  max_iterations:       3,
  min_iterations:       minIterations,   // ← NEW
  complexity: {
    word_count:       wordCount,
    has_analytical:   hasAnalytical,
    has_multi_req:    hasMultiReq
  }
};
return [{ json: item }];

const g = $getWorkflowStaticData('global');
const s = g.reflection_state;

const FORMAT_RULE = `FORMATTING RULE: Respond in plain text only. Do not use any markdown formatting — no headers (##, ###), no bold (**text**), no italic (*text*), no bullet points with asterisks or dashes, no horizontal rules. Use plain paragraphs. You may use numbered lists (1. 2. 3.) when listing steps or items, but nothing else.`;

const promptText = s.iteration === 1
  ? `You are a helpful, knowledgeable assistant. Respond naturally and appropriately to the following — if it is a greeting, reply in a friendly way; if it is a question, answer it clearly and thoroughly; if it is a technical or academic topic, provide depth and structure.

${FORMAT_RULE}

Input: ${s.input_text}`
  : `You are a helpful assistant. A reviewer found specific issues with your previous response. Revise it to fully address every point in the feedback.

${FORMAT_RULE}

Original input:
${s.input_text}

Your previous response:
${s.current_draft}

Reviewer feedback:
${s.critic_feedback}

Produce a revised response that directly fixes all issues raised.`;

return [{ json: { input_text: s.input_text, prompt_text: promptText } }];

const item  = $input.first().json;
const g     = $getWorkflowStaticData('global');
const s     = g.reflection_state;
const draft = (item.text || '').trim();
g.reflection_state = { ...s, current_draft: draft };
const promptText =
`You are a strict quality reviewer. Evaluate whether the response below is the best possible answer to the input. Apply the rubric that fits the nature of the input — do NOT impose academic criteria on casual or simple inputs.

Input: ${s.input_text}

Response to evaluate (iteration ${s.iteration} of 3):
${draft}

Evaluate on ALL five universal dimensions:
1. RELEVANCE — Does the response directly and fully address what was asked or said?
2. ACCURACY — Is everything stated factually correct?
3. COMPLETENESS — Does the response cover everything the input reasonably expects?
4. CLARITY — Is the response easy to understand, well-phrased and appropriately concise?
5. APPROPRIATENESS — Does the tone and format match the input type?

Scoring rules:
- Each dimension is worth 2 points (max 10 total)
- Score 9–10: The response is exactly right — nothing to improve
- Score 7–8: Good but has a clear weakness in at least one dimension
- Score 5–6: Noticeably off in tone, completeness or accuracy
- Score 1–4: Wrong, irrelevant or severely mismatched

Respond ONLY with valid JSON — no other text, no markdown fences:
{
  "verdict": "pass" or "fail",
  "score": <integer 1-10>,
  "dimension_scores": {
    "relevance": <0-2>,
    "accuracy": <0-2>,
    "completeness": <0-2>,
    "clarity": <0-2>,
    "appropriateness": <0-2>
  },
  "feedback": "<what is wrong or confirm it is correct>",
  "strengths": "<what was done well>",
  "improvements": "<specific fixes needed, empty string if pass>"
}

Important: verdict must be "pass" only if score is 9 or 10.`;
return [{ json: { prompt_text: promptText } }];

const item    = $input.first().json;
const g       = $getWorkflowStaticData('global');
const s       = g.reflection_state;
const rawText = (item.text || '').trim();

let verdict='fail', score=5, feedback=rawText, strengths='', improvements='', dimScores={};
try {
  const m = rawText.match(/\{[\s\S]*\}/);
  if (m) {
    const p   = JSON.parse(m[0]);
    verdict      = (p.verdict || 'fail').toLowerCase().trim();
    score        = Number.isInteger(p.score) ? p.score : parseInt(p.score) || 5;
    feedback     = p.feedback     || rawText;
    strengths    = p.strengths    || '';
    improvements = p.improvements || '';
    dimScores    = p.dimension_scores || {};
  }
} catch(e) { verdict='fail'; feedback=rawText; }

const criticPasses  = verdict === 'pass' && score >= 9;
const minIterMet    = s.iteration >= (s.min_iterations || 1);
const capReached    = s.iteration >= s.max_iterations;
const isApproved    = criticPasses && minIterMet;
const isDone        = isApproved || capReached;

let terminationReason = 'continue';
if      (isApproved && criticPasses) terminationReason = 'quality_threshold_met';
else if (capReached)                 terminationReason = 'max_iterations_safety_cap';

const fullFeedback = [
  feedback,
  improvements ? `\nImprovements required:\n${improvements}` : '',
  Object.keys(dimScores).length ? `\nDimension scores: ${JSON.stringify(dimScores)}` : ''
].join('');

// Token estimates for this iteration
const genTok  = Math.ceil((s.current_draft || '').length / 4);
const critTok = Math.ceil(rawText.length / 4);

// Accumulate per-iteration log entry into global state
const iterEntry = {
  iteration:  s.iteration,
  generator: {
    output:         s.current_draft,
    token_estimate: genTok
  },
  critic: {
    verdict,
    score,
    dimension_scores: dimScores,
    feedback,
    strengths,
    improvements,
    token_estimate: critTok
  }
};

g.reflection_state = {
  ...s,
  iteration:         s.iteration + 1,
  critic_feedback:   fullFeedback,
  is_approved:       isApproved,
  iterations_log:    [...(s.iterations_log || []), iterEntry],
  total_gen_tokens:  (s.total_gen_tokens  || 0) + genTok,
  total_crit_tokens: (s.total_crit_tokens || 0) + critTok
};

return [{ json: {
  current_draft:           s.current_draft,
  current_iteration:       s.iteration,
  critic_verdict:          verdict,
  critic_score:            score,
  critic_dimension_scores: dimScores,
  critic_feedback:         feedback,
  critic_strengths:        strengths,
  critic_improvements:     improvements,
  is_approved:             isApproved,
  cap_reached:             capReached,
  is_done:                 isDone,
  termination_reason:      terminationReason,
  min_iterations:          s.min_iterations || 1,
  complexity:              s.complexity || {},
  input_text:              s.input_text,
  start_time_ms:           s.start_time_ms,
  input_token_estimate:    s.input_token_estimate,
  max_iterations:          s.max_iterations
} }];

const data   = $input.first().json;
const endMs  = Date.now();
const latMs  = endMs - data.start_time_ms;
const latSec = parseFloat((latMs / 1000).toFixed(2));

const iterationsRun  = data.iterations_run || 0;
const llmCallsActual = iterationsRun * 2;   // 1 generator + 1 critic per iteration
const llmCallsMax    = 6;                   // max 3 iterations × 2 LLM calls

const inpTok         = data.input_token_estimate || 0;
const genTok         = data.total_gen_tokens     || 0;
const critTok        = data.total_crit_tokens    || 0;
const totalOutputTok = genTok + critTok;
const totalTok       = inpTok + totalOutputTok;

return [{ json: {

  user_prompt:  data.input_text,
  final_answer: data.final_answer,

  metadata: {
    pattern:          'Reflection — Generate-Evaluate-Revise Loop',
    pattern_category: 'Single-Agent Reasoning Pattern',
    run_timestamp:    new Date().toISOString(),
    model:            'qwen2.5:14b',
    model_provider:   'Ollama (local)',
    latency_ms:       latMs,
    latency_seconds:  latSec,
    llm_calls_actual: llmCallsActual,
    llm_calls_max:    llmCallsMax,
    token_usage: {
      total_input_tokens:  inpTok,
      total_output_tokens: totalOutputTok,
      total_tokens:        totalTok
    },
    status:             'completed',
    termination_reason: data.termination_reason || 'unknown'
  },

  execution_trace: {

    reflection_turns: (data.iterations_log || []).map(t => ({
      iteration:  t.iteration,
      generator: {
        output:         t.generator.output,
        token_estimate: t.generator.token_estimate
      },
      critic: {
        verdict:          t.critic.verdict,
        score:            t.critic.score,
        dimension_scores: t.critic.dimension_scores,
        feedback:         t.critic.feedback,
        strengths:        t.critic.strengths,
        improvements:     t.critic.improvements,
        token_estimate:   t.critic.token_estimate
      }
    })),

    complexity_classification: {
      word_count:              (data.complexity || {}).word_count     || 0,
      has_analytical:          (data.complexity || {}).has_analytical || false,
      has_multi_req:           (data.complexity || {}).has_multi_req  || false,
      min_iterations_assigned: data.min_iterations || 1
    },

    reflection_summary: {
      total_iterations:      iterationsRun,
      max_iterations:        data.max_iterations || 3,
      min_iterations:        data.min_iterations || 1,
      exited_early:          iterationsRun < (data.max_iterations || 3),
      quality_threshold_met: data.is_approved,
      safety_cap_triggered:  data.cap_reached,
      final_critic_score:    data.final_critic_score,
      final_dimension_scores: data.final_dimension_scores || {}
    },

    structural_properties: {
      orchestration_type: 'AI-driven – generate-evaluate-revise cycle',
      loop_mechanism:     'direct cycle edge: Exit Gate FALSE → Format Generator Prompt',
      state_passing:      "$getWorkflowStaticData('global') carries current_draft + critic_feedback + iterations_log",
      termination_conditions: [
        'critic score >= 9 AND iteration >= min_iterations → quality_threshold_met',
        'iteration >= 3 → max_iterations_safety_cap'
      ],
      termination_logic:     'Complexity Classifier sets min_iterations; Critic evaluates quality; Code enforces both',
      evaluation_dimensions: ['relevance', 'accuracy', 'completeness', 'clarity', 'appropriateness'],
      scope:                 'universal – greetings, daily questions and technical/academic queries'
    },

    llm_limitation: 'n8n Ollama node (lmChatOllama typeVersion 1) does not expose a temperature parameter — metadata.temperature is therefore null. Temperature is governed by the Ollama server default (typically 0.8). To override it, set the value in the Ollama Modelfile or replace the native Ollama node with an HTTP Request node and pass temperature in the request body. Token counts are character-length estimates (chars ÷ 4) because the Ollama node does not return token usage data natively.'
  }

}}];
